// Every screen of the app as a mockup, built from tokens.css, ui.css and screens.css. screen.html?s=<id>&t=ink|ivory
// &g=leaf|brass|line renders one; index.html lists them. Content is the app's own words.

// ---------- The shell ----------
const titlebar = (place, bare) => `<header class="titlebar"><button class="icon-btn icon-btn--sm" aria-label="Back">${ico('back')}</button><button class="icon-btn icon-btn--sm" aria-label="Forward">${ico('fwd')}</button><span class="place">${place}</span>
  ${bare ? '' : `<button class="find">${ico('search')}<span>Find a friend, group, server or channel</span><kbd>Ctrl K</kbd></button>`}
  <span class="win-ctl"><span>${ico('min')}</span><span>${ico('max')}</span><span>${ico('close')}</span></span></header>`
function rail(sel = 'home') {
  const t = (id, k, extra = '') => `<button class="rail-tile" ${sel === id ? 'aria-current="page"' : ''} aria-label="${id}">${picture(K[k])}${extra}</button>`
  return `<nav class="rail" aria-label="Servers and groups"><button class="rail-tile home" ${sel === 'home' ? 'aria-current="page"' : ''} aria-label="Home">${emblem}</button><span class="sep"></span>
    ${t('owls', 'owls', '<span class="count">4</span>')}${t('raid', 'raid')}${t('trio', 'trio')}
    <button class="rail-tile add push" aria-label="Create or join">${ico('plus')}</button></nav>`
}
const userbar = (sub = '<span class="t-mono" style="color:var(--ink-3)">ann#7095</span>', muted = false) => `<div class="userbar">${av('ann', '', 'on')}<span class="who"><span class="t-name">Ann</span>${sub}</span>
  <span class="ctl"><button class="icon-btn" aria-label="Mute" ${muted ? 'aria-pressed="true"' : ''}>${ico(muted ? 'micoff' : 'mic')}</button><button class="icon-btn" aria-label="Deafen">${ico('head')}</button><button class="icon-btn" aria-label="Settings">${ico('gear')}</button></span></div>`
const voicebar = (where) => `<div class="voicebar"><div class="top"><span class="signal">${ico('signal')}Voice connected</span><span class="ctl">
  <button class="icon-btn icon-btn--sm" aria-label="Turn on camera">${ico('cam')}</button><button class="icon-btn icon-btn--sm" aria-label="Share your screen">${ico('screen')}</button><button class="icon-btn icon-btn--sm" aria-label="Noise suppression">${ico('wave')}</button><button class="icon-btn icon-btn--sm icon-btn--danger" aria-label="Disconnect">${ico('hang')}</button></span></div>
  <button class="link t-meta" style="justify-self:start;color:var(--ink-2);text-decoration:none">${where}</button></div>`
const foot = (inCall, where) => `<div class="foot">${inCall ? voicebar(where) : ''}${userbar(inCall ? '<span class="t-meta voice">In voice</span>' : undefined, inCall)}</div>`
const win = (o) => `<div class="win ${o.cls ?? ''}">${titlebar(o.place)}${rail(o.rail)}${o.side}${foot(o.call, o.where)}<main class="main">${o.main}</main>${o.right ?? ''}${o.over ?? ''}</div>`

// ---------- Rows ----------
const dm = (k, sub, o = {}) => { const tag = o.end?.includes('<button') ? 'div' : 'button'; return `<${tag} class="row row--two ${o.unread ? 'unread' : ''}" ${o.sel ? 'aria-current="page"' : ''}>${av(k, '', o.pr ?? 'on')}<span class="who"><span class="nm">${NAME[k]}</span><span class="sub ${o.subCls ?? ''}">${sub}</span></span>${o.end ?? ''}</${tag}>` }
const chan = (name, o = {}) => `<button class="row ${o.unread ? 'unread' : 'read'}" ${o.sel ? 'aria-current="page"' : ''}><span class="hash">${ico(o.voice ? 'speaker' : 'hash')}</span><span class="who"><span class="nm">${name}</span></span>${o.count ? `<span class="end"><span class="count">${o.count}</span></span>` : ''}</button>`
const label = (t, n, add) => `<h2 class="group-label">${t}${n !== undefined ? `<span class="n">${n}</span>` : ''}${add ? `<button class="icon-btn icon-btn--sm" aria-label="Add">${ico('plus')}</button>` : ''}</h2>`
const member = (k, sub, o = {}) => `<button class="row row--two">${av(k, '', o.pr ?? 'on')}<span class="who"><span class="nm" ${o.color ? `style="color:${o.color}"` : ''}>${NAME[k]}${o.you ? ' <span class="t-meta">(you)</span>' : ''}</span><span class="sub ${o.subCls ?? ''}">${sub}</span></span></button>`
const idCard = `<div class="side-foot"><div class="card id-card"><div class="top"><span class="t-label">Friend ID</span><button class="icon-btn icon-btn--sm" aria-label="Copy friend ID">${ico('copy')}</button></div><span class="t-mono">ann#7095</span><span class="t-hint">Unique key <span class="t-mono">02F2E7</span></span></div></div>`
const homeSide = (selFriends = true, extra = '') => `<aside class="side"><div class="side-head"><h1>Home</h1></div><div class="side-body">
  <button class="row" ${selFriends ? 'aria-current="page"' : ''}><span class="hash">${ico('users')}</span><span class="who"><span class="nm">Friends</span></span><span class="end"><span class="count">1</span></span></button>
  ${label('Direct messages')}${dm('mira', 'Counter-Strike 2', { subCls: 'game', pr: 'game', unread: true, end: '<span class="end"><span class="count">2</span></span>', sel: !selFriends && extra === 'mira' })}${dm('dov', 'In voice: Lounge', { subCls: 'voice', pr: 'voice' })}${dm('theo', 'Back in December', { pr: '' })}
  ${label('Groups', undefined, true)}<button class="row row--two"><span class="av sq">${picture(K.trio)}</span><span class="who"><span class="nm">The Trio</span><span class="sub">3 members, 2 online</span></span></button>
  </div>${idCard}</aside>`

// ---------- Chat ----------
const msg = (k, time, lines, o = {}) => `<div class="msg ${o.cls ?? ''}">${av(k, 'av--lg')}<div class="h"><span class="t-name">${NAME[k]}</span><span class="t-time">${time}</span>${o.seal ? `<span title="Sealed by ${NAME[k]}: written by their key" aria-label="Sealed by ${NAME[k]}">${ico('key', 'seal')}</span>` : ''}</div>${lines.map((l) => `<p>${l}</p>`).join('')}${o.extra ?? ''}${o.state ?? ''}</div>`
const composer = (to, o = {}) => `<form class="composer ${o.focus ? 'focus' : ''}"><button class="icon-btn" type="button" aria-label="Attach a file">${ico('clip')}</button><button class="icon-btn" type="button" aria-label="Choose a GIF">${ico('gif')}</button><span class="${o.typed ? 'typed' : 'ph'}">${o.typed ?? `Message ${to}`}</span><button class="icon-btn" aria-label="Send" ${o.typed ? '' : 'disabled'}>${ico('send')}</button></form>`
const chatMain = (head, messages, to, o = {}) => `<div class="main-head">${head}</div>${o.top ?? ''}<div class="chat">${o.day === false ? '' : '<p class="day-rule">Today</p>'}${messages}</div>${composer(to, o)}`

// ---------- Two weeks of play, the theme, the cards ----------
function days(o = {}) {
  if (o.off) return `<section class="days"><h3>Two weeks of play</h3><p class="empty">${o.mine ? 'Activity is off. Turn it on in Settings, Activity.' : 'Not shared'}</p></section>`
  const play = o.play ?? PLAY, sum = play.reduce((a, b) => a + b, 0), date = (i) => new Date(2026, 10, 22 - (13 - i)).toLocaleDateString('en-GB', { weekday: 'long', day: 'numeric', month: 'long' })
  const cells = play.map((m, i) => `<span class="cell ${i === 13 ? 'today' : ''} ${o.focus === i ? 'is-focus' : ''}" data-l="${level(m)}" role="listitem" aria-label="${date(i)}: ${m ? m + ' min' : 'no play'}"></span>`).join('')
  const tip = o.tip !== undefined ? `<span class="float tip days-tip" style="left:clamp(0px, calc(${(o.tip + 0.5) / 14 * 100}% - 24px), calc(100% - 200px))"><b>${date(o.tip)}</b><span><span>Counter-Strike 2</span><span>2.3 h</span></span><span><span>Dota 2</span><span>45 min</span></span></span>` : ''
  return `<section class="days"><h3>Two weeks of play <span class="t-time">${sum ? (sum / 60).toFixed(1) + ' h' : 'none'}</span></h3><div class="cells" role="list">${cells}${tip}</div></section>`
}
// The weave behind a card moves only away from the text's luminance: darker than the card in Ink (light text), lighter
// in Ivory (dark text). Every pixel then has at least the plain card's contrast, however strong the weave.
const THEME_FLAT = () => (document.documentElement.dataset.theme === 'light' ? { L: 0.995, C: 0.018 } : { L: 0.12, C: 0.06 })
// The theme layer, as ThemeLayer in the build draws it: the weave (and for Parallax a second one, for Shimmer a band of
// the weave's lightest tone) under a scrim of the card's colour, moving by an effect from effects.js
const themeLayer = (k, th) => {
  if (!th) return ''
  const fx = th.fx && FX.includes(th.fx) ? th.fx : null, d = Math.round((th.depth ?? 60) / 10), f = THEME_FLAT(), light = `oklch(${f.L} ${f.C} ${+tones(bytesOf(K[k]), th.shift)[2].match(/(\d+)\)$/)[1]})`
  const delay = th.at !== undefined && fx ? `animation-delay:${-(FX_TIME[fx][0] / (th.speed ?? 1)) * th.at}s;animation-play-state:paused` : ''
  const mv = (n) => `<span class="wv${n ? ' wv2' : ''}"><span class="mv" style="${delay}">${weave(K[k], th.kind, th.shift + (n ? 25 : 0), false, THEME_FLAT())}</span></span>`
  return `<span class="theme-layer ${fx ? `fx-${fx} d-${d}` : ''} ${th.at !== undefined ? 'paused' : ''}" style="--op:${th.op / 100};--scrim:0%;--spd:${th.speed ?? 1};--band:${light}">${mv(0)}${fx === 'parallax' ? mv(1) : ''}${fx === 'shimmer' ? `<span class="band" style="${delay}"></span>` : ''}</span>`
}
const MIRA_THEME = { kind: 2, shift: 40, op: 30, depth: 60, fx: 'drift' }
function smallCard(k, o = {}) {
  return `<div class="pop float" role="dialog" aria-label="${NAME[k]}'s profile" style="--person:${accentOf(K[k])};${o.pos ?? ''}">${themeLayer(k, o.theme)}<div class="bnr">${o.art ? `<span class="art ${o.art}"></span>` : weave(K[k], o.weave ?? 0)}</div><button class="icon-btn icon-btn--sm icon-btn--on-art expand" aria-label="Open full profile">${ico('expand')}</button>
    <span class="face">${av(k, 'av--xl', 'on')}</span><div class="body"><h2 class="t-title">${NAME[k]}</h2><p class="t-mono handle">${HANDLE[k]}</p>${o.status === false ? '' : `<p class="status">${o.status ?? 'Ranked tonight, quiet after eleven'}</p>`}${days(o.days ?? {})}
    <p class="t-body" style="color:var(--ink-2)">Entry fragger. Mirage or nothing.</p>${o.mine ? '' : '<p class="presence"><i></i>Online, direct</p>'}
    ${o.game ? `<button class="row row--two glance"><span class="art cs2"></span><span class="who"><span class="nm">Counter-Strike 2</span><span class="sub">Mirage, Competitive, round 12</span></span><span class="t-number">7–4</span></button>` : ''}
    ${o.mine ? '' : `<form class="composer note"><span class="ph">Message ${NAME[k]}</span><button class="icon-btn" aria-label="Send" disabled>${ico('send')}</button></form>`}</div></div>`
}
function fullCard(k, o = {}) {
  return `<div class="pop float full" role="dialog" aria-label="Profile of ${NAME[k]}" style="--person:${accentOf(K[k])}">${themeLayer(k, o.theme)}<div class="bnr">${weave(K[k], 0)}</div><button class="icon-btn icon-btn--on-art close" style="position:absolute;right:12px;top:12px;z-index:3" aria-label="Close">${ico('close')}</button>
    <span class="face">${av(k, 'av--xxl', 'on')}</span><div class="acts"><button class="btn btn--primary">${ico('send')}Message</button><button class="btn">${ico('phone')}Call</button><button class="icon-btn" aria-label="More">${ico('more')}</button></div>
    <div class="body"><h2 class="t-title">${NAME[k]}</h2><p class="t-mono" style="color:var(--ink-3)">${HANDLE[k]}</p><p class="status">Ranked tonight, quiet after eleven</p>${days()}<p class="presence"><i></i>Online, direct</p>
    <div class="tabs" role="tablist"><button class="tab" role="tab" aria-selected="true">About</button><button class="tab" role="tab">Activity</button><button class="tab" role="tab">In common</button></div>
    <dl class="kv"><dt>About</dt><dd>Entry fragger. Mirage or nothing.</dd><dt>On Eleusinia since</dt><dd>March 2026</dd><dt>Last played</dt><dd>Counter-Strike 2, 2 hours ago</dd></dl>
    ${o.recent ? `<section class="recent decision"><h3 class="t-label">Recently played <span class="t-hint">· waiting for your yes or no</span></h3><ol>${[['cs2', 'Counter-Strike 2', 'Today, 21:10'], ['dota', 'Dota 2', 'Yesterday'], ['d2', 'Destiny 2', '19 November'], ['mar', 'Marathon', '9 November'], ['hd', 'Helldivers 2', '1 November']].map(([a, g, t]) => `<li><span class="art ${a}"></span><span class="t-name">${g}</span><span class="t-time">${t}</span></li>`).join('')}</ol></section>` : ''}
    <dl class="card idplate"><dt>Unique key</dt><dd><span class="t-mono">7F3A 91C2</span><button class="link t-meta">We compared it: mark as verified</button></dd></dl></div></div>`
}

// ---------- The call (kept from the build: tall user cards side by side, the speaker lit; restyled) ----------
const ucard = (k, st, o = {}) => `<figure class="ucard ${o.speaking ? 'speaking' : ''}">${o.speaking ? `<span class="seam" style="--seam:${o.seam ?? 64}px"></span>` : ''}<span class="bnr">${weave(K[k], undefined, 0, false)}</span>${o.muted ? `<span class="mic" aria-label="Muted">${ico('micoff')}</span>` : ''}${av(k, '')}<figcaption><button class="link t-name" style="color:var(--ink);text-decoration:none">${NAME[k]}${o.you ? '' : ''}</button></figcaption><span class="st ${o.speaking ? 'talk' : o.muted ? 'mute' : ''}">${st}</span></figure>`
const oculus = (cards) => `<section class="oculus" aria-label="In the call">${cards}</section>`
const ptile = (k, o = {}) => `<figure class="ptile ${o.speaking ? 'speaking' : ''} ${o.cam ? 'cam' : ''}">${o.cam ? '<span class="shown"></span>' : `<span class="bnr">${weave(K[k], undefined, 0)}</span>${av(k)}`}<figcaption class="nm">${o.you ? 'You' : NAME[k]}</figcaption></figure>`
const shared = `<span class="shown art cs2"></span>`
const stage = (o = {}) => `<section class="stage"><div class="stage-bar"><span class="t-meta">Mira is showing her screen · 1080p, 60 fps</span><button class="btn btn--sm">${ico('leave')}Leave stream</button><button class="btn btn--sm btn--quiet">Hide video</button></div>
  <div class="screen ${o.tall ? 'tall' : ''}">${shared}<span class="who">${av('mira', 'av--sm')}Mira's screen · through Dov</span><span class="tools"><button class="icon-btn icon-btn--sm icon-btn--on-art" aria-label="Volume">${ico('speaker')}</button><button class="icon-btn icon-btn--sm icon-btn--on-art" aria-label="Full screen">${ico('expand')}</button></span></div>
  ${o.folded ? `<div class="fold"><button class="btn btn--sm btn--quiet">${ico('chev')}Show the people in the call</button></div>` : `<div class="people-row">${ptile('mira', { speaking: o.speak === 'mira' })}${ptile('ann', { you: true, cam: o.cams })}${ptile('dov', { speaking: o.speak === 'dov', cam: o.cams })}${ptile('rae')}</div><div class="fold"><button class="btn btn--sm btn--quiet">${ico('chev')}Hide the people in the call</button></div>`}</section>`
const serverSide = (sel = 'plans', o = {}) => `<aside class="side server"><div class="srv-head"><span class="banner">${o.art ? `<span class="art ${o.art}"></span>` : weave(K.owls, 0)}</span><span class="nm"><b>${o.name ?? 'Night Owls'}</b><span>24 members, 6 here</span></span><button class="icon-btn icon-btn--sm icon-btn--on-art" aria-haspopup="menu" aria-label="Server menu">${ico('chev')}</button></div>
  <div class="side-body">${label('Text channels', 3, true)}${chan('general', { sel: sel === 'general' })}${chan('plans', { sel: sel === 'plans' })}${chan('clips', { unread: true, count: 4 })}
  ${label('Voice channels', 2, true)}${chan('Lounge', { voice: true, sel: sel === 'Lounge' })}<div class="voice-people">${['dov', 'rae', 'mira', ...(o.annIn ? ['ann'] : [])].map((k) => `<button class="row">${av(k, 'av--sm')}<span class="who"><span class="nm">${NAME[k]}</span></span>${k === 'mira' ? '<span class="end"><span class="live">Live</span></span>' : ''}</button>`).join('')}</div>${chan('Squad', { voice: true })}</div></aside>`
const membersCol = () => `<aside class="right"><div class="body">${label('Officers', 2)}${member('dov', 'In voice: Lounge', { pr: 'voice', subCls: 'voice' })}${member('rae', 'In voice: Lounge', { pr: 'voice', subCls: 'voice' })}
  ${label('Online', 4)}${member('ann', 'Online', { you: true })}${member('mira', 'Sharing in Lounge', { pr: 'voice', subCls: 'voice' })}${member('pim', 'In voice: Lounge', { pr: 'voice', subCls: 'voice' })}${member('lux', 'Destiny 2', { pr: 'game', subCls: 'game' })}
  ${label('Offline', 18)}${member('theo', 'Last seen yesterday', { pr: '' })}${member('sol', 'Last seen Tuesday', { pr: '' })}</div></aside>`
const callScreen = (o) => win({ place: 'Night Owls · Lounge', rail: 'owls', call: true, where: 'Lounge · Night Owls', side: serverSide('Lounge', { annIn: true }),
  main: `<div class="main-head"><span class="hash" style="color:var(--ink-3)">${ico('speaker')}</span><h1>Lounge</h1><span class="t-meta">four in the call</span><span class="end"><button class="icon-btn" aria-label="Invite to voice channel">${ico('userplus')}</button></span></div>
    ${o.stage ? stage(o) : oculus(`${ucard('dov', o.speak === 'dov' ? 'Talking' : 'Dota 2', { speaking: o.speak === 'dov', seam: 88 })}${ucard('rae', 'Muted', { muted: true })}${ucard('ann', o.speak === 'ann' ? 'Talking' : 'You', { speaking: o.speak === 'ann' })}${ucard('mira', o.speak === 'mira' ? 'Talking' : 'Counter-Strike 2', { speaking: o.speak === 'mira', seam: 56 })}`)}
    <div class="chat" style="justify-content:flex-end">${msg('dov', '21:38', ['one more round then I\'m on'])}${msg('mira', '21:41', ['9 to 7, we\'re winning for once'])}</div>${composer('Lounge')}`,
  right: membersCol() })

// ---------- Settings ----------
const PANES = [['You', [['profile', 'My profile'], ['activity', 'Activity'], ['privacy', 'Privacy and safety']]], ['App', [['appearance', 'Appearance'], ['voice', 'Voice and video'], ['hotkeys', 'Hotkeys'], ['storage', 'Storage'], ['help', 'Help and feedback'], ['account', 'Account']]]]
const sw = (on, lab, sub) => `<label class="set-row"><span class="what"><span class="t-name">${lab}</span>${sub ? `<span class="t-hint">${sub}</span>` : ''}</span><button class="switch" role="switch" aria-checked="${on}" aria-label="${lab}"></button></label>`
const field = (lab, val, o = {}) => `<label class="field"><span class="t-label">${lab}</span><input class="input ${o.cls ?? ''}" ${val ? `value="${val}"` : ''} placeholder="${o.ph ?? ''}" ${o.invalid ? 'aria-invalid="true"' : ''}>${o.err ? `<span class="error">${ico('alert')}${o.err}</span>` : ''}${o.hint ? `<span class="t-hint">${o.hint}</span>` : ''}</label>`
const sel = (lab, val) => `<label class="field"><span class="t-label">${lab}</span><select class="select"><option>${val}</option></select></label>`
const slider = (lab, v, out) => `<label class="field"><span class="t-label" style="display:flex">${lab}<span class="t-time" style="margin-left:auto;font-style:normal">${out}</span></span><input type="range" class="slider" style="--v:${v}%" value="${v}"></label>`
const preview = (draft) => `<aside class="preview"><span class="t-label">What others see</span>${smallCard('ann', { mine: true, status: 'Exams until Friday', days: {}, theme: draft })}</aside>`
const PANE = {
  profile: () => `<h2>My profile</h2><div class="block">${field('Display name', 'Ann')}${field('About you', 'I am Ann')}<div class="btn-row"><button class="btn btn--primary">Save</button></div></div>
    <div class="block"><h3>Status</h3><div class="grid-2">${field('What are you up to?', 'Exams until Friday')}${sel('Clear after', 'Today')}</div>${sw(false, 'Quiet: no pokes', 'Invites to a voice channel wait until you clear your status')}<div class="btn-row"><button class="btn">Set status</button><button class="btn btn--quiet">Clear status</button></div></div>
    <div class="block"><h3>Run as administrator</h3><div class="set-row"><span class="what"><span class="t-name">Restart Eleusinia as administrator</span><span class="t-hint">So hotkeys and the overlay reach games that run as administrator</span></span><button class="btn">Restart</button></div></div>
    <div class="block"><h3>Banner</h3><div class="weaves">${['Your picture', 'Arcade', 'Skyline', 'Bands', 'Lattice'].map((n, i) => `<button class="tile-choice" role="radio" aria-checked="${i === 3}">${i ? weave(K.ann, i - 1) : picture(K.ann)}<span>${n}</span></button>`).join('')}</div>${sw(true, "Show the game's art as my banner while I play")}</div>`,
  theme: () => `<h2>My profile</h2><div class="block"><h3>Profile theme</h3><p class="hint">A weave behind your whole card, small and full. Everyone who opens your profile sees it.</p>
    <span class="t-label">Weave</span><div class="weaves"><button class="tile-choice none" role="radio" aria-checked="false"><span>None</span></button>${['Arcade', 'Skyline', 'Bands', 'Lattice'].map((n, i) => `<button class="tile-choice" role="radio" aria-checked="${i === 0}">${weave(K.ann, i, 40)}<span>${n}</span></button>`).join('')}</div>
    ${slider('Tones', 11, '40°')}${slider('Strength', 73, '45 %')}<div class="field"><span class="t-label">Motion</span><div class="seg" role="radiogroup"><button role="radio" aria-checked="false">Off</button>${FX.map((f) => `<button role="radio" aria-checked="${f === 'drift'}">${FX_NAMES[f]}</button>`).join('')}</div></div>
    <div class="grid-2">${slider('Speed', 33, '1×')}${slider('Depth', 56, '60 %')}</div><p class="hint">Held still for anyone who asks their system for less motion.</p><div class="btn-row"><button class="btn btn--primary">Save theme</button><button class="btn">Reset</button></div></div>`,
  activity: () => `<h2>Activity</h2><div class="block">${sw(true, "Share what I'm playing", 'Friends and group members see the game, never anyone else')}${sw(true, 'Playtime', 'Hours played, and your two weeks of play')}${sw(true, 'Achievements')}${sw(false, 'Genre, developer and release date')}</div>
    <div class="block"><h3>Connections</h3><div class="connections"><button class="row row--two conn"><span class="logo">S</span><span class="what"><span class="t-name">Steam</span><span class="t-meta online-text">CS2 live</span></span>${ico('chev')}</button><button class="row row--two conn"><span class="logo">B</span><span class="what"><span class="t-name">Bungie.net</span><span class="t-meta">Linked as Rivensbane#1990</span></span>${ico('chev')}</button></div></div>
    <div class="block"><h3>Hidden from</h3><p class="hint">Nobody. Hide your activity from someone in their profile's menu.</p><div class="btn-row"><button class="btn">Add a game…</button></div></div>`,
  privacy: () => `<h2>Privacy and safety</h2><div class="block">${sw(true, 'Let people find me by username', 'From four letters, people online can find you by the start of your username')}${sw(true, 'Share diagnostics with the developers when they ask', 'Only after a problem report; nothing identifying')}${sw(true, 'Relay for friends', 'Always on: your computer may carry encrypted voice and text for friends who cannot connect directly')}</div>
    <div class="block"><h3>Blocked people</h3><p class="hint">Nobody. Block someone from their profile, or by right-clicking them.</p></div>`,
  appearance: () => `<h2>Appearance</h2><div class="block"><h3>Theme</h3><div class="theme-cards" role="radiogroup">${[[['#0f121a'], 'Ink', true], [['#ebe4d4'], 'Ivory'], [['#0f121a', '#ebe4d4'], 'Match Windows']].map(([c, n, on]) => `<button class="tile-choice" role="radio" aria-checked="${!!on}"><span class="swatch">${c.map((x) => `<i style="background:${x}"></i>`).join('')}</span><span>${n}</span></button>`).join('')}</div></div>
    <div class="block"><h3>Sounds</h3>${slider('Master volume', 70, '70 %')}${sw(true, 'Join and leave sounds')}${sw(true, 'Message sounds while the window is in the background')}</div>`,
  voice: () => `<h2>Voice and video</h2><div class="block"><div class="grid-2">${sel('Microphone', 'System default')}${sel('Speakers', 'System default')}</div>${slider('Mic sensitivity', 40, '−48 dB')}<div class="meter" style="--v:34%"><i></i></div><p class="hint">Join a call to see your level here.</p>
    ${sw(true, 'Noise suppression', 'Removes steady noise such as fans and keyboards')}${sw(false, 'Push to talk')}</div><div class="block"><h3>Quality</h3><div class="field"><span class="t-label">Voice bitrate</span><div class="seg" role="radiogroup"><button role="radio">32 kbps</button><button role="radio" aria-checked="true">64 kbps</button><button role="radio">128 kbps</button></div></div></div>`,
  hotkeys: () => `<h2>Hotkeys</h2><div class="block"><p class="hint">Work in every app, games included. None are set until you set them.</p>${[['Mute', 'Ctrl Shift M'], ['Deafen', ''], ['Push to talk', '']].map(([n, k]) => `<div class="set-row"><span class="what"><span class="t-name">${n}</span></span><span class="hotkey"><kbd class="${k ? '' : 'unset'}">${k || 'Not set'}</kbd><button class="btn btn--sm">Set</button>${k ? '<button class="btn btn--sm btn--quiet">Clear</button>' : ''}</span></div>`).join('')}</div>
    <p class="hint">For games that run as administrator, restart Eleusinia as administrator: Settings, My profile.</p></div>`,
  storage: () => `<h2>Storage</h2><div class="block"><div class="set-row"><span class="what"><span class="t-name">Pictures and files kept</span><span class="t-hint">412 MB of 1.00 GB</span></span><select class="select" style="width:160px"><option>1.00 GB</option></select></div><div class="meter" style="--v:41%"><i></i></div><div class="btn-row"><button class="btn">Clear the cache</button><button class="btn btn--quiet">${ico('folder')}Show the folder</button></div></div>`,
  help: () => `<h2>Help and feedback</h2><div class="block"><h3>Report a problem</h3><p class="hint">Sends a description and the app's recent diagnostics to the developers. You see everything first; nothing identifying is included.</p>${field('What happened?', '', { ph: 'The call dropped when Mira started sharing' })}<div class="btn-row"><button class="btn btn--primary">Send report</button><button class="btn btn--quiet">Preview what is sent</button></div></div>
    <div class="block"><h3>Version</h3><div class="set-row"><span class="what"><span class="t-name">Eleusinia 0.1.10</span><span class="t-hint">Up to date, checked 4 minutes ago</span></span><button class="btn">${ico('refresh')}Check for updates</button></div></div>`,
  account: () => `<h2>Account</h2><div class="block"><dl class="card idplate"><dt>Friend ID</dt><dd><span class="t-mono">ann#7095</span><button class="icon-btn icon-btn--sm" aria-label="Copy">${ico('copy')}</button></dd><dt>Unique key</dt><dd><span class="t-mono">02F2 E7A1 9C44 0B6D</span></dd></dl></div>
    <div class="block"><h3>Your identity</h3><p class="hint">A file that brings this account to another computer. Keep it private: whoever has it is you.</p><div class="btn-row"><button class="btn">Export my identity</button></div></div><div class="danger-zone"><span class="what"><span class="t-name">Delete this account</span><span class="t-hint">Removes your identity, messages and settings from this computer. Friends keep what you sent them.</span></span><button class="btn btn--danger">${ico('trash')}Delete</button></div>`,
}
function settings(pane, o = {}) {
  const idx = PANES.map(([g, rows]) => `${label(g)}${rows.map(([id, n]) => `<button class="row" ${id === (pane === 'theme' ? 'profile' : pane) ? 'aria-current="true"' : ''}><span class="who"><span class="nm">${n}</span></span></button>`).join('')}`).join('')
  return win({ place: 'Settings', rail: 'home', side: homeSide(), main: chatMain('<h1>Friends</h1>', '', 'Mira'), over: `<div class="backdrop"><div class="dialog float settings" role="dialog" aria-label="Settings"><header class="dlg-bar"><h1>Settings</h1><button class="icon-btn" aria-label="Close">${ico('close')}</button></header><nav class="index">${idx}</nav><div class="pane">${PANE[pane]()}</div>${preview(pane === 'theme' ? { kind: 0, shift: 40, op: 45, depth: 60, fx: 'drift' } : null)}</div></div>` })
}

// ---------- Server settings ----------
const SPAGES = ['Overview', 'Roles', 'Members', 'Channels', 'Invites', 'Bans', 'Audit log']
const tri = (v) => `<span class="seg seg--sm" role="radiogroup"><button class="deny" role="radio" aria-checked="${v === 'deny'}" aria-label="Deny">${ico('x')}</button><button role="radio" aria-checked="${v === 'inherit'}" aria-label="Take it from the role">${ico('slash')}</button><button class="allow" role="radio" aria-checked="${v === 'allow'}" aria-label="Allow">${ico('check')}</button></span>`
const SPANE = {
  Overview: () => `<div class="block"><div class="setup portrait" style="position:static;display:flex;gap:16px;align-items:center"><span class="av av--xl sq">${picture(K.owls)}</span><div class="btn-row"><button class="btn">Choose a picture</button><button class="btn">${ico('gif')}GIF</button></div></div>${field('Server name', 'Night Owls')}</div>
    <div class="block"><h3>Banner</h3><div style="position:relative;height:120px;border-radius:var(--r-2);overflow:hidden">${weave(K.owls, 0)}<span style="position:absolute;inset:0;background:linear-gradient(180deg,transparent 40%,var(--scrim-art))"></span><span style="position:absolute;left:16px;bottom:12px;color:var(--on-art);font:var(--type-section)">Night Owls</span></div><div class="seg" role="radiogroup"><button role="radio" aria-checked="true">From the server's key</button><button role="radio">A picture</button><button role="radio">A GIF</button><button role="radio">A game's art</button></div>${slider('Darkness', 45, '45 %')}<div class="btn-row"><button class="btn btn--primary">Save changes</button><button class="btn btn--quiet">Reset</button><button class="btn btn--quiet">Use the default</button></div></div>`,
  Roles: () => `<div class="grid-2" style="grid-template-columns:260px 1fr;align-items:start"><div class="block"><span class="t-label">Highest first</span>${[['Officers', '#cfae69', 2], ['Raiders', '#93a9cf', 9], ['@everyone', '#969080', 24]].map(([n, c, m], i) => `<button class="row" ${i === 0 ? 'aria-current="true"' : ''}><span class="grip">${ico('grip')}</span><span class="role-dot" style="background:${c}"></span><span class="who"><span class="nm">${n}</span></span><span class="end t-time">${m}</span></button>`).join('')}<div class="btn-row"><button class="btn btn--quiet">${ico('plus')}Create a role</button></div></div>
    <div class="block">${field('Role name', 'Officers')}${sw(true, 'Show members apart', 'Listed under their own heading in the members column')}<span class="t-label">Permissions</span>${sw(true, 'Manage channels')}${sw(true, 'Kick and ban members')}${sw(false, 'Manage roles', 'Only roles below this one')}<div class="btn-row"><button class="btn btn--primary">Save changes</button><button class="btn btn--quiet">Reset</button></div><div class="danger-zone"><span class="what"><span class="t-name">Delete Officers</span><span class="t-hint">Its two members keep their other roles.</span></span><button class="btn btn--danger">Delete role</button></div></div></div>`,
  Members: () => `<div class="block"><div class="with-icon">${ico('search')}<input class="input" placeholder="Search 24 members"></div><div class="table">${[['dov', 'Officers', 'Joined March 2026'], ['rae', 'Officers', 'Joined March 2026'], ['mira', 'Raiders', 'Joined April 2026'], ['lux', 'Raiders', 'Joined May 2026'], ['theo', '—', 'Joined June 2026']].map(([k, r, j]) => `<div class="tr" style="grid-template-columns:1fr 160px 180px 40px"><span style="display:flex;gap:12px;align-items:center">${av(k)}<span class="t-name">${NAME[k]}</span></span><span class="t-meta" style="display:flex;align-items:center;gap:8px">${r === '—' ? 'No role' : `<span class="role-dot" style="background:${r === 'Officers' ? '#cfae69' : '#93a9cf'}"></span>${r}`}</span><span class="t-meta">${j}</span><button class="icon-btn icon-btn--sm" aria-label="More">${ico('more')}</button></div>`).join('')}</div></div>`,
  Channels: () => `<div class="grid-2" style="grid-template-columns:240px 1fr;align-items:start"><div class="block">${label('Text channels')}${chan('general', { sel: true })}${chan('plans')}${label('Voice channels')}${chan('Lounge', { voice: true })}<div class="btn-row"><button class="btn btn--quiet">${ico('plus')}Create a channel</button></div></div>
    <div class="block">${field('Channel name', 'general')}${field('Topic', "Friday's raid and who brings what")}<span class="t-label">Who may do what</span><div class="table"><div class="tr th" style="grid-template-columns:1fr 112px 112px 112px"><span>Role</span><span>See it</span><span>Write</span><span>Manage</span></div>${[['@everyone', 'inherit', 'allow', 'deny'], ['Officers', 'allow', 'allow', 'allow'], ['Raiders', 'inherit', 'inherit', 'deny']].map(([r, ...v]) => `<div class="tr" style="grid-template-columns:1fr 112px 112px 112px"><span class="t-name">${r}</span>${v.map(tri).join('')}</div>`).join('')}</div><p class="hint">✕ deny, / take it from the role, ✓ allow.</p><div class="btn-row"><button class="btn btn--primary">Save changes</button><button class="btn btn--quiet">Reset</button></div><div class="danger-zone"><span class="what"><span class="t-name">Delete #general</span><span class="t-hint">Its messages are deleted for everyone.</span></span><button class="btn btn--danger">Delete channel</button></div></div></div>`,
  Invites: () => `<div class="block"><div class="btn-row">${sel('Expires', 'After 7 days')}${sel('Uses', 'No limit')}<button class="btn btn--primary" style="align-self:end">Create link</button></div><div class="table">${[['eleusinia://invite/Qm9…a8Xk', 'Dov', '3 uses · expires in 6 days'], ['eleusinia://invite/Lp2…0Hn', 'Rae', '1 of 5 uses · expires tomorrow']].map(([l, by, u]) => `<div class="tr" style="grid-template-columns:1fr 120px 220px auto"><span class="t-mono">${l}</span><span class="t-meta">by ${by}</span><span class="t-meta">${u}</span><button class="btn btn--sm btn--danger">Revoke</button></div>`).join('')}</div></div>`,
  Bans: () => `<div class="block"><div class="empty-state"><h2>Nobody is banned</h2><p>A banned person cannot join again, even with an invite. Ban someone from the members list.</p></div></div>`,
  'Audit log': () => `<div class="block"><p class="hint">Newest first.</p><div class="table">${[['dov', 'changed the server’s name or picture', 'Night Owls', '21:40'], ['rae', 'created an invite', 'expires in 6 days', '20:12'], ['dov', 'gave a role', 'Raiders to Mira', 'Yesterday'], ['dov', 'made the server', '', '3 Nov']].map(([k, w, t, at]) => `<div class="tr" style="grid-template-columns:32px 1fr 80px">${av(k)}<span class="t-body"><span class="t-name">${NAME[k]}</span> ${w}${t ? ` <span class="t-meta">· ${t}</span>` : ''}</span><span class="t-time">${at}</span></div>`).join('')}</div></div>`,
}
const serverSettings = (page) => win({ place: 'Night Owls · plans', rail: 'owls', side: serverSide(), main: chatMain(`<span class="hash" style="color:var(--ink-3)">${ico('hash')}</span><h1>plans</h1>`, '', '#plans'), right: membersCol(),
  over: `<div class="backdrop"><div class="dialog float srv-settings" role="dialog" aria-label="Server settings"><header class="dlg-bar"><span class="av sq">${picture(K.owls)}</span><h1>Night Owls</h1><span class="t-meta">Server settings</span><button class="icon-btn" aria-label="Close">${ico('close')}</button></header><nav class="index">${SPAGES.map((p) => `<button class="row" ${p === page ? 'aria-current="true"' : ''}><span class="who"><span class="nm">${p}</span></span></button>`).join('')}</nav><div class="pane"><h2>${page}</h2>${SPANE[page]()}</div></div></div>` })

// ---------- Home ----------
const artCard = (a, game, line, k, act, live) => `<article class="art-card"><span class="art ${a}"></span><span class="top"><span>${game}</span>${live ? '<span class="live">LIVE</span>' : ''}</span><div class="txt"><span class="line">${line}</span><span class="foot-row">${av(k, 'av--sm')}${NAME[k]}<button class="btn btn--sm">${ico(act === 'Join' ? 'phone' : 'send')}${act}</button></span></div></article>`
const homeMain = (o = {}) => `<div class="main-head"><h1>Friends</h1><span class="t-meta">six here, three at play</span><span class="end"><button class="btn btn--primary">${ico('userplus')}Add a friend</button></span></div><div class="main-body">
  <div class="with-icon">${ico('search')}<input class="input" placeholder="Username (4+ letters) or friend ID" ${o.q ? `value="${o.q}"` : ''}></div>${o.top ?? ''}
  <section><div class="sec-head"><h2>Playing now</h2><span class="n">3</span></div></section>
  <div class="art-cards">${artCard('cs2', 'Counter-Strike 2', 'Mirage, 9 to 7', 'mira', 'Message', true)}${artCard('d2', 'Destiny 2', "Salvation's Edge", 'sol', 'Message')}${artCard('dota', 'Dota 2', 'Anti-Mage, 14 to 21', 'dov', 'Join', true)}</div>
  <section><div class="sec-head"><h2>Live calls</h2><span class="n">2</span></div></section>
  <div class="call-cards"><div class="card call-card"><span class="faces">${av('dov')}${av('rae')}${av('pim')}</span><span style="display:grid"><span class="t-name">Lounge, Night Owls</span><span class="t-meta">Dov, Rae and Pim · Mira is sharing</span></span><button class="btn btn--sm">${ico('phone')}Join</button></div><div class="card call-card"><span class="faces">${av('mira')}${av('theo')}</span><span style="display:grid"><span class="t-name">The Trio</span><span class="t-meta">Mira and Theo</span></span><button class="btn btn--sm">${ico('phone')}Join</button></div></div>
  <section><div class="sec-head"><h2>Online</h2><span class="n">2</span></div><div class="people-list" style="margin-top:8px">${dm('mira', 'Playing Counter-Strike 2 · Mirage 9–7', { subCls: 'game', pr: 'game' })}${dm('pim', 'Online, connecting…', { pr: 'on' })}</div></section></div>`
const homeScreen = (o = {}) => win({ place: 'Friends', rail: 'home', side: homeSide(), main: homeMain(o), over: o.over })

// ---------- The screens ----------
const S = {}
S.splash = () => `<div class="win">${titlebar('', true)}<div class="splash"><div class="inner"><span class="mark">${emblem}</span><span class="t-wordmark">Eleusinia</span><span class="steps"><span class="t-body">Catching up with your groups</span><span class="t-hint">2 of 3 friends linked · Theo is still connecting</span></span><span class="bar"><i></i></span></div></div></div>`
S.setup = (err) => `<div class="win">${titlebar('Create your account', true)}<div class="setup"><form class="panel card"><span style="display:flex;align-items:center;gap:12px;color:var(--gold)"><span style="width:40px;height:40px">${emblem}</span><span class="t-title" style="color:var(--ink)">Create your account</span></span><p class="t-meta">Your account lives on this computer. Nobody else holds it, so keep this computer, or export your identity later.</p>
  <div class="portrait">${av('ann', 'av--xl')}<div class="btn-row"><button class="btn" type="button">Choose a picture</button><button class="btn btn--quiet" type="button">${ico('gif')}GIF</button></div></div>
  ${field('Username', err ? 'a' : 'ann', err ? { invalid: true, err: 'Usernames are 2 to 20 characters: letters, numbers, dots and underscores' } : { hint: 'Letters, numbers, dots and underscores. A random number is added to make your friend ID.' })}${field('Display name', 'Ann')}${field('About you (optional)', '', { ph: 'A line people see on your profile' })}
  <div class="btn-row" style="justify-content:flex-end"><button class="btn btn--primary btn--lg" ${err ? '' : 'aria-busy="false"'}>Enter Eleusinia</button></div></form></div></div>`
S['setup-error'] = () => S.setup(true)
S.home = () => homeScreen()
S['home-empty'] = () => win({ place: 'Friends', rail: 'home', side: `<aside class="side"><div class="side-head"><h1>Home</h1></div><div class="side-body"><button class="row" aria-current="page"><span class="hash">${ico('users')}</span><span class="who"><span class="nm">Friends</span></span></button>${label('Direct messages')}<p class="t-hint" style="padding:0 12px">Conversations show here once a message is sent.</p>${label('Groups', undefined, true)}<p class="t-hint" style="padding:0 12px">No groups yet. Create one to talk with several friends at once.</p></div>${idCard}</aside>`,
  main: `<div class="main-head"><h1>Friends</h1><span class="t-meta">nobody yet</span><span class="end"><button class="btn btn--primary">${ico('userplus')}Add a friend</button></span></div><div class="main-body"><div class="with-icon">${ico('search')}<input class="input" placeholder="Username (4+ letters) or friend ID"></div><div class="empty-state"><h2>No friends yet</h2><p>Search for someone's friend ID above. Your own ID is in the column on the left for them to find you.</p></div></div>` })
S['home-requests'] = () => homeScreen({ q: 'theo#5531', top: `<section class="card" style="padding:8px"><span class="group-label" style="padding-top:4px">Found</span>${dm('theo', 'theo#5531 · offline, found by their ID card', { pr: '', end: '<span class="end"><button class="btn btn--sm">Add friend</button></span>' })}<span class="group-label">Requests</span>${dm('lux', 'Wants to be your friend', { end: '<span class="end"><button class="btn btn--sm">Accept</button><button class="btn btn--sm btn--quiet">Ignore</button></span>' })}${dm('pim', 'Online, can’t connect yet · request sent', { end: '<span class="end"><button class="btn btn--sm" disabled>Sent</button></span>' })}</section>` })
const dmMain = (o = {}) => chatMain(`${av('mira', '', 'game')}<span style="display:grid"><h1>Mira</h1><span class="t-meta">mira#2210 · Counter-Strike 2</span></span><span class="end"><button class="chip chip--online">${ico('lock')}Private · direct</button><button class="btn">${ico('phone')}Call</button></span>`,
  o.msgs ?? `${msg('mira', '21:38', ['one more round then I\'m on'])}${msg('ann', '21:40', ['take your time, Dov\'s already in the lounge'], { seal: true })}${msg('mira', '21:41', ['9 to 7, we\'re winning for once', 'save me a seat'])}`, 'Mira', o)
const personPanel = (k = 'mira') => `<aside class="right" style="--person:${accentOf(K[k])}"><div style="position:relative;height:112px">${weave(K[k], 0)}</div><div style="padding:0 16px 16px;display:grid;gap:6px;margin-top:-40px;position:relative">${av(k, 'av--xl', k === 'mira' ? 'game' : '')}<h2 class="t-title">${NAME[k]}</h2><p class="t-mono" style="color:var(--ink-3)">${HANDLE[k]}</p><p class="t-meta">${k === 'mira' ? 'Ranked tonight, quiet after eleven' : 'Back in December'}</p>${days(k === 'mira' ? {} : { off: true })}<p class="t-body" style="color:var(--ink-2)">Entry fragger. Mirage or nothing.</p><hr class="rule"><span class="t-label">Together</span><p class="t-meta">Talked 4 h over 9 calls · last today</p><span class="t-label">In common</span><p class="t-meta">Night Owls, The Trio</p></div></aside>`
S.dm = () => win({ place: 'Mira', rail: 'home', side: homeSide(false, 'mira'), main: dmMain(), right: personPanel() })
S['dm-pending'] = () => win({ place: 'Theo', rail: 'home', side: homeSide(false), main: chatMain(`${av('theo', '', '')}<span style="display:grid"><h1>Theo</h1><span class="t-meta">theo#5531 · Online, can't connect yet</span></span><span class="end"><button class="btn" disabled>${ico('phone')}Call</button></span>`,
  `${msg('theo', 'Yesterday', ['back in December, exams'])}${msg('ann', '21:43', ['good luck! send me the notes when you can'], { state: '<span class="state">Waiting to send</span>' })}${msg('ann', '21:44', ['also the link from earlier'], { cls: 'cont', state: `<span class="state failed">Couldn’t send · <button class="link">Delete</button></span>` })}`, 'Theo', {
  top: `<div style="padding:12px 24px 0"><div class="banner-error">${ico('alert')}<span class="what"><span class="t-name">Theo can't be reached yet</span><span class="t-meta">Their router turns direct connections away, and no friend or Eleusinia relay could carry this yet. Eleusinia keeps trying.</span></span><button class="btn btn--sm">Try again now</button></div></div>` }), right: personPanel('theo') })
S.group = () => win({ place: 'The Trio', rail: 'trio', side: `<aside class="side"><div class="side-head"><button class="btn btn--quiet" style="padding-left:4px">${ico('back')}Home</button></div><div class="side-body"><div style="display:grid;justify-items:center;gap:8px;padding:16px 0"><span class="av av--xl sq">${picture(K.trio)}</span><h2 class="t-section">The Trio</h2><span class="t-meta">3 members, 2 online</span></div><button class="btn btn--primary" style="justify-self:center">${ico('phone')}Start call</button>${label('Direct messages')}${dm('mira', 'Counter-Strike 2', { subCls: 'game', pr: 'game' })}${dm('dov', 'In voice: Lounge', { subCls: 'voice', pr: 'voice' })}</div></aside>`,
  main: chatMain(`<span class="av sq">${picture(K.trio)}</span><span style="display:grid"><h1>The Trio</h1><span class="t-meta">3 members · 2 online</span></span><span class="end"><button class="icon-btn" aria-label="Add member">${ico('userplus')}</button><button class="icon-btn" aria-label="Leave group">${ico('leave')}</button></span>`, `${msg('theo', '20:02', ['who has the map for tomorrow?'])}${msg('mira', '20:05', ['me, sending it now'], { extra: '<div class="msg-img"></div>' })}`, 'The Trio'),
  right: `<aside class="right"><div class="body">${label('Online', 2)}${member('ann', 'Online', { you: true })}${member('mira', 'Counter-Strike 2', { pr: 'game', subCls: 'game' })}${label('Offline', 1)}${member('theo', 'Last seen today', { pr: '' })}</div></aside>` })
S.server = () => win({ place: 'Night Owls · plans', rail: 'owls', side: serverSide(), main: chatMain(`<span class="hash" style="color:var(--ink-3)">${ico('hash')}</span><h1>plans</h1><span class="t-meta">Friday's raid and who brings what</span><span class="end"><button class="icon-btn" aria-label="Members">${ico('users')}</button></span>`,
  `${msg('dov', '20:12', ['raid Friday at nine, who\'s in?', 'bring your own snacks this time'])}${msg('rae', '20:15', ['in. I\'ll invite Lux, she cleared it last week'], { seal: true })}${msg('ann', '20:18', ['count me in'])}`, '#plans'), right: membersCol() })
S['server-long'] = () => `<div style="display:flex;gap:24px">${win({ cls: 'small', place: 'The Midnight Cartographers…', rail: 'owls', side: serverSide('plans', { name: "The Midnight Cartographers' Society of Very Long Server Names" }), main: chatMain(`<span class="hash" style="color:var(--ink-3)">${ico('hash')}</span><h1>plans</h1>`, msg('dov', '20:12', ['raid Friday at nine']), '#plans') })}</div>`
S['call-quiet'] = () => callScreen({})
S['call-talking'] = () => callScreen({ speak: 'mira' })
S['call-share'] = () => callScreen({ stage: true, speak: 'mira' })
S['call-share-folded'] = () => callScreen({ stage: true, folded: true, tall: true })
