const menu = (items, pos) => `<div class="float menu" role="menu" style="position:absolute;z-index:20;${pos}">${items.map((i) => (i === '-' ? '<div class="menu-sep"></div>' : i.startsWith('#') ? `<div class="menu-head">${i.slice(1)}</div>` : `<button class="menu-item ${i.includes('!') ? 'menu-item--danger' : ''} ${i.includes('~') ? 'is-hover' : ''}" role="menuitem">${i.replace(/[!~]/g, '').replace(/ ▸$/, '')}${i.endsWith('▸') ? `<span class="end">${ico('fwd')}</span>` : ''}</button>`)).join('')}</div>`
S['menu-channel'] = () => win({ place: 'Night Owls · plans', rail: 'owls', side: serverSide(), main: chatMain(`<span class="hash" style="color:var(--ink-3)">${ico('hash')}</span><h1>plans</h1>`, msg('dov', '20:12', ['raid Friday at nine, who\'s in?']), '#plans'), right: membersCol(),
  over: menu(['Mark as read', '~Mute channel ▸', 'Copy link', '-', 'Edit channel', 'Duplicate channel', 'Invite people', '-', '!Delete channel'], 'left:300px;top:250px') + menu(['For 15 minutes', 'For 1 hour', 'For 8 hours', 'Until I turn it back on'], 'left:524px;top:286px') })
S['menu-person'] = () => win({ place: 'Night Owls · Lounge', rail: 'owls', call: true, where: 'Lounge · Night Owls', side: serverSide('Lounge', { annIn: true }), main: chatMain(`<h1>Lounge</h1>`, '', 'Lounge'), right: membersCol(),
  over: `<div class="float menu" role="menu" style="position:absolute;z-index:20;left:250px;top:200px;width:250px"><button class="menu-item" role="menuitem">Profile</button><button class="menu-item" role="menuitem">Message</button><button class="menu-item" role="menuitem">Start a call</button><div class="menu-sep"></div><div class="menu-head">User volume</div><div style="padding:4px 12px 8px">${slider('', 80, '80 %')}</div><button class="menu-item" role="menuitemcheckbox" aria-checked="true">Mute<span class="end tick">${ico('check')}</span></button><button class="menu-item" role="menuitemcheckbox">Disable video</button><button class="menu-item" role="menuitemcheckbox">Ignore</button><div class="menu-sep"></div><button class="menu-item" role="menuitem">Server mute</button><button class="menu-item is-hover" role="menuitem">Move to<span class="end">${ico('fwd')}</span></button><button class="menu-item menu-item--danger" role="menuitem">Disconnect</button></div>` })
S['menu-add'] = () => win({ place: 'Friends', rail: 'home', side: homeSide(), main: homeMain(), over: menu(['Create a server', 'Join with an invite', 'Create a group'], 'left:84px;top:560px') })
S.tooltips = () => win({ place: 'Settings', rail: 'home', side: homeSide(), main: homeMain(), over: `<div class="backdrop"><div class="dialog float settings">${`<header class="dlg-bar"><h1>Settings</h1><button class="icon-btn" aria-label="Close">${ico('close')}</button></header><nav class="index">${PANES.map(([g, rows]) => `${label(g)}${rows.map(([id, n]) => `<button class="row" ${id === 'voice' ? 'aria-current="true"' : ''}><span class="who"><span class="nm">${n}</span></span></button>`).join('')}`).join('')}</nav><div class="pane">${PANE.voice()}<div class="float tip" style="left:520px;top:236px"><b>Mic sensitivity</b>Sounds quieter than this line are not sent. Speak normally and set it just under your voice.</div></div>${preview(null)}`}</div></div><div class="float tip" style="left:900px;top:100px;z-index:40"><b>Saturday 21 November</b>Counter-Strike 2 · 2.3 h<br>Dota 2 · 45 min</div>` })
S.toasts = () => homeScreen({ over: `<div class="notices"><button class="float notice">${av('mira', 'av--sm')}<span><b>Mira</b> started playing <span class="game">Counter-Strike 2</span></span></button><button class="float notice">${av('dov', 'av--sm')}<span><b>Dov</b> joined Lounge</span></button></div>
  <div class="float toast" style="right:24px;bottom:24px">${ico('poke')}<span class="what"><span class="t-name">Rae invites you to Lounge</span><span class="t-meta">Night Owls · for the next 2 minutes</span></span><button class="btn btn--primary btn--sm">Join</button><button class="btn btn--quiet btn--sm">Dismiss</button></div>
  <div class="float toast" style="right:24px;bottom:96px"><span class="what"><span class="t-name">Still connecting to Theo</span><span class="t-meta">Startup is done; messages to Theo go out once linked.</span></span><button class="icon-btn icon-btn--sm" aria-label="Dismiss">${ico('close')}</button></div>` })
S['gif-picker'] = () => win({ place: 'Mira', rail: 'home', side: homeSide(false, 'mira'), main: dmMain({ typed: 'gg' }), right: personPanel(), over: `<div class="backdrop"><div class="dialog float" style="width:640px"><div class="dlg-head"><h2 class="t-section">Choose a GIF</h2><button class="icon-btn close" aria-label="Close">${ico('close')}</button></div><div class="dlg-body"><div class="tabs" role="tablist"><button class="tab" role="tab" aria-selected="true">Search</button><button class="tab" role="tab">Starred</button><button class="tab" role="tab">Recent</button><button class="tab" role="tab">Upload a GIF</button></div><div class="with-icon">${ico('search')}<input class="input" value="good game"></div><div class="gif-grid">${['cs2', 'dota', 'd2', 'mar', 'hd', 'cs2', 'd2', 'dota'].map((a, i) => `<span><span class="art ${a}" style="position:absolute;inset:0"></span><button class="icon-btn icon-btn--sm icon-btn--on-art star" aria-label="Star">${ico('star')}</button></span>`).join('')}</div><p class="t-hint">Search by KLIPY. The GIF you pick is downloaded once and sent like a file.</p></div></div></div>` })
S['rich-chat'] = () => win({ place: 'Night Owls · plans', rail: 'owls', side: serverSide(), right: membersCol(), main: chatMain(`<span class="hash" style="color:var(--ink-3)">${ico('hash')}</span><h1>plans</h1>`,
  `${msg('rae', '20:15', ['in. I\'ll invite Lux'], { extra: `<div class="card attach-card">${`<span class="av av--lg sq">${picture(K.raid)}</span>`}<span class="what"><span class="t-name">Friday Raid</span><span class="t-meta">You're invited · 6 members</span></span><button class="btn btn--sm">Join</button></div>` })}
   ${msg('dov', '20:20', ['<button class="link">https://fog.example/notes</button>'], { extra: '<div class="card link-card"><div class="txt"><span class="t-meta">fog.example</span><span class="t-name">A page about fog</span><span class="t-meta">Mist over stone, all day.</span></div><span class="thumb"></span></div>' })}
   ${msg('ann', '20:24', ['the build order'], { extra: `<div class="card attach-card"><span class="ico">${ico('file')}</span><span class="what"><span class="t-name">raid-plan.pdf</span><span class="t-meta">1.2 MB · from Ann</span></span><button class="btn btn--sm">${ico('down')}Save</button><button class="btn btn--sm btn--quiet">Show in folder</button></div>`, seal: true })}`, '#plans') })
