S.crash = () => homeScreen({ over: `<div class="backdrop"><div class="dialog float" style="width:520px"><div class="dlg-head"><h2 class="t-section">Eleusinia stopped working</h2></div><div class="dlg-body"><p class="t-body">The window closed after an error. Your messages and calls are safe; reopening loads everything again.</p><div class="banner-error">${ico('alert')}<span class="what"><span class="t-name">Renderer crashed</span><span class="t-meta t-mono">exit code 0xC0000005 · 21:47</span></span></div>${sw(true, 'Send a crash report', 'Diagnostics only, nothing identifying; you can see it first')}</div><div class="dlg-foot"><button class="btn btn--quiet">See the report</button><button class="btn btn--primary">Reopen</button></div></div></div>` })
S.errors = () => win({ place: 'Mira', rail: 'home', side: homeSide(false, 'mira'), main: dmMain({ top: `<div style="padding:12px 24px 0;display:grid;gap:8px"><div class="banner-error">${ico('alert')}<span class="what"><span class="t-name">That picture is too large to use</span><span class="t-meta">Pictures go up to 400 KB after cropping; GIFs up to 25 MB.</span></span><button class="icon-btn icon-btn--sm" aria-label="Dismiss">${ico('close')}</button></div></div>`,
  msgs: `${msg('mira', '21:38', ['one more round then I\'m on'])}${msg('ann', '21:40', ['here are the clips'], { extra: `<div class="card attach-card"><span class="ico" style="color:var(--danger)">${ico('alert')}</span><span class="what"><span class="t-name">clips.zip</span><span class="error">Couldn't send: the file was moved or deleted</span></span><button class="btn btn--sm">Choose again</button></div>` })}` }), right: personPanel() })

// Phase 1 extras: type specimen, buttons in context with every state, gold side by side
S.specimen = () => `<div class="win" style="display:block;overflow:auto"><div style="padding:32px 40px;display:grid;grid-template-columns:1fr 1fr;gap:28px 48px">${[
  ['wordmark', '--type-wordmark', '<span class="t-wordmark">Eleusinia</span>'], ['screen title · name on a card', '--type-title', '<span class="t-title">Friends</span> &nbsp; <span class="t-title">Mira</span>'], ['score · light level', '--type-number', '<span class="t-number">7–4</span> &nbsp; <span class="t-number">2010</span>'],
  ['section heading · empty-state title · server on its banner', '--type-section', '<span class="t-section">Playing now</span> &nbsp; <span class="t-section">No friends yet</span>'], ['group label · field label · column head', '--type-label', '<span class="t-label">Direct messages</span> &nbsp; <span class="t-label">Display name</span> &nbsp; <span class="t-label">See it</span>'],
  ['body · inputs · menu items · links', '--type-body', '<span class="t-body">raid Friday at nine, who\'s in? bring your own snacks this time</span>'], ['name in a list · message author · tab', '--type-name', '<span class="t-name">Mira</span> · <span class="t-name">general</span> · <span class="t-name">My profile</span>'],
  ['button label', '--type-button', '<button class="btn btn--primary">Add a friend</button> <button class="btn">Call</button>'], ['secondary line · hint · tooltip', '--type-meta', '<span class="t-meta">Playing Counter-Strike 2 · Mirage 9–7</span><br><span class="t-hint">Letters, numbers, dots and underscores.</span>'],
  ['timestamp · delivery state', '--type-time', '<span class="t-time">21:41 · Delivered · Yesterday</span>'], ['count', '--type-badge', '<span class="count">4</span> <span class="count">12</span> <span class="live">LIVE</span> <kbd>Ctrl K</kbd>'],
  ['friend ID · key · code', '--type-mono', '<span class="t-mono">mira#2210 · 7F3A 91C2 · -gamestateintegration</span>'], ['Non-Latin names fall back per glyph', 'fallbacks', '<span class="t-title">Мира · 美羅 · Μίρα</span> <span class="t-name">Ярослав · 李小龍 · Θεόδωρος</span>'],
].map(([job, tok, ex]) => `<div style="display:grid;gap:6px;border-top:1px solid var(--line);padding-top:12px"><span class="t-time">${tok}</span><span class="t-meta">${job}</span><div>${ex}</div></div>`).join('')}</div></div>`
S.buttons = () => settings('profile').replace('<div class="pane">', `<div class="pane"><div class="block"><h3>Every button, every state</h3><div class="table">${[['Primary', 'btn btn--primary', 'Save'], ['Secondary', 'btn', 'Edit profile'], ['Quiet', 'btn btn--quiet', 'Clear status'], ['Destructive', 'btn btn--danger', 'Delete']].map(([n, c, l]) => `<div class="tr" style="grid-template-columns:90px repeat(6, 1fr)"><span class="t-meta">${n}</span><button class="${c}">${l}</button><button class="${c} is-hover">${l}</button><button class="${c} is-press">${l}</button><button class="${c} is-focus">${l}</button><button class="${c}" disabled>${l}</button><button class="${c}" aria-busy="true">${l}</button></div>`).join('')}<div class="tr th" style="grid-template-columns:90px repeat(6, 1fr)"><span></span><span>rest</span><span>hover</span><span>pressed</span><span>focus</span><span>disabled</span><span>loading</span></div>
  <div class="tr" style="grid-template-columns:90px repeat(6, 1fr)"><span class="t-meta">Icon</span><button class="icon-btn">${ico('gear')}</button><button class="icon-btn is-hover">${ico('gear')}</button><button class="icon-btn is-press">${ico('gear')}</button><button class="icon-btn is-focus">${ico('gear')}</button><button class="icon-btn" disabled>${ico('gear')}</button><button class="icon-btn" aria-pressed="true">${ico('micoff')}</button></div>
  <div class="tr" style="grid-template-columns:90px repeat(6, 1fr)"><span class="t-meta">Switch</span><button class="switch" role="switch" aria-checked="false"></button><button class="switch is-hover" role="switch" aria-checked="false"></button><button class="switch" role="switch" aria-checked="true"></button><button class="switch is-focus" role="switch" aria-checked="true"></button><button class="switch" role="switch" aria-checked="true" disabled></button><button class="check" role="checkbox" aria-checked="true">${ico('check')}</button></div>
  <div class="tr" style="grid-template-columns:90px 1fr 1fr 1fr"><span class="t-meta">Row</span><button class="row">${av('mira', 'av--sm')}<span class="who"><span class="nm">Mira</span></span></button><button class="row is-hover">${av('mira', 'av--sm')}<span class="who"><span class="nm">Mira</span></span></button><button class="row" aria-current="true">${av('mira', 'av--sm')}<span class="who"><span class="nm">Mira</span></span></button></div>
  <div class="tr" style="grid-template-columns:90px 1fr 1fr 1fr"><span class="t-meta">Choice</span><div class="seg" role="radiogroup"><button role="radio" aria-checked="true">Off</button><button role="radio" class="is-hover">Drift</button><button role="radio">Breathe</button></div><span class="btn-row"><button class="chip chip--online">${ico('lock')}Private · direct</button><button class="chip is-hover">Officers</button></span><span class="btn-row"><button class="link">Delete</button><select class="select" style="width:130px"><option>Today</option></select></span></div></div></div>`)


S.effects = () => `<div class="win" style="display:block;height:auto;padding:24px;overflow:visible"><div style="display:grid;gap:20px">${FX.map((fx) => `<section class="fx-strip"><div style="display:grid;gap:4px"><h2 class="t-section">${FX_NAMES[fx]}</h2><p class="t-hint">${{ drift: 'The weave slides slowly corner to corner and back', breathe: 'It fades and swells in and out', orbit: 'It circles slowly round', tide: 'It sways from side to side', shimmer: 'A soft band of its lightest tone passes across', parallax: 'Two layers of it move against each other' }[fx]}</p><p class="t-time">${FX_TIME[fx][0]} s a cycle at 1×, ${Math.round(FX_TIME[fx][1] / FX_TIME[fx][0])} steps a second</p></div>${[0, 0.25, 0.5, 0.75].map((at) => `<div style="display:grid;gap:4px"><span class="t-time">${Math.round(at * 100)} %</span>${smallCard('mira', { mine: true, status: 'Ranked tonight, quiet after eleven', theme: { kind: 2, shift: 40, op: 45, depth: 60, speed: 1, fx, at }, days: {} }).replace('style="--person', 'style="position:relative;width:100%;--person')}</div>`).join('')}</section>`).join('')}</div></div>`

window.SCREENS = S
